### types.ts
```typescript
export type NotificationChannel = 'in-app' | 'push' | 'email';
export type NotificationType = 'comment' | 'mention' | 'like' | 'follow' | 'system' | 'reminder' | 'approval' | string;
export type NotificationAction = 'reply' | 'approve' | 'dismiss' | 'view';
export type NotificationStatus = 'read' | 'unread';

export interface NotificationPreferences {
  channels: {
    [channel in NotificationChannel]: {
      enabled: boolean;
      types: { [type in NotificationType]?: boolean };
    };
  };
  batching: {
    enabled: boolean;
    windowMs: number;
    maxBatchSize: number;
  };
  quietHours: {
    enabled: boolean;
    start: string; // HH:mm
    end: string; // HH:mm
    timezone: string;
  };
}

export interface Notification {
  id: string;
  type: NotificationType;
  title: string;
  body: string;
  status: NotificationStatus;
  readAt?: string;
  channel: NotificationChannel[];
  data?: Record<string, unknown>;
  actions?: NotificationAction[];
  metadata: {
    createdAt: string;
    deliveredAt?: string;
    readAt?: string;
    batchId?: string;
    sourceId?: string;
    url?: string;
    icon?: string;
  };
}

export interface BatchedNotification {
  id: string;
  notifications: Notification[];
  summary: string;
  count: number;
  windowStart: string;
  windowEnd: string;
  delivered: boolean;
}

export interface WebSocketMessage {
  type: 'notification' | 'read-sync' | 'batch' | 'preference-sync' | 'pong';
  payload: unknown;
  timestamp: string;
}

export interface OfflineAction {
  id: string;
  type: NotificationAction;
  notificationId: string;
  payload?: Record<string, unknown>;
  timestamp: string;
  retries: number;
}

export interface ConnectionState {
  status: 'connected' | 'disconnected' | 'reconnecting';
  lastConnected?: string;
  retryCount: number;
  maxRetries: number;
}
```

### notification-service.ts
Core service:
- WebSocket connection with auto-reconnect
- Subscribe/unsubscribe to notifications
- Mark as read (syncs to server)
- Fetch history (paginated for infinite scroll)
- Handle incoming messages
- Event emitter pattern for decoupling

### preferences-service.ts
- Load/save preferences
- Check if notification should be delivered (preference check)
- Channel preference routing

### batch-manager.ts
- Accumulate notifications in a time window
- When window ends or max size reached, emit batch
- Create batched summary
- Deliver via appropriate channels

### offline-manager.ts
- Detect online/offline
- Queue actions when offline
- Replay when online
- IndexedDB or localStorage-backed queue

### action-handler.ts
- Dispatch action (reply, approve, dismiss)
- Communicate with server
- Handle offline queueing

### Components
- NotificationCenter: main container with infinite scroll
- NotificationItem: single notification with actions
- NotificationPreferences: preferences form

### Hooks
- useNotifications: React hook that ties everything together

Let me now build this. I'll create a new project with package.json and all source files.

For testing, I'll use vitest since it's fast and has good ESM support. Let me include React Testing Library for component tests.

